<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class PaymentAdmin {
 public static function register(): void { add_action('admin_menu',[self::class,'menu']); add_action('admin_post_avanik_payment_verify',[self::class,'verify']); }
 public static function menu(): void { add_submenu_page('avanik-providers','Payment Verification','Payment Verification','manage_options','avanik-payment-verification',[self::class,'render']); }
 public static function render(): void { if(!current_user_can('manage_options'))return; global $wpdb; $rows=$wpdb->get_results("SELECT * FROM ".PaymentRepository::table_name()." WHERE status='pending_verification' ORDER BY created_at ASC",ARRAY_A)?:[]; ?><div class="wrap" dir="rtl"><h1>تأیید پرداخت‌ها</h1><table class="widefat striped"><thead><tr><th>Payment</th><th>Booking</th><th>مبلغ</th><th>رسید</th><th>عملیات</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5">پرداختی برای بررسی وجود ندارد.</td></tr><?php endif; foreach($rows as $p): $m=json_decode((string)$p['metadata'],true)?:[]; ?><tr><td><?php echo esc_html($p['payment_id']); ?></td><td><?php echo esc_html($p['booking_id']); ?></td><td><?php echo esc_html(number_format((float)$p['amount']).' '.$p['currency']); ?></td><td><?php if(!empty($m['receipt_url'])):?><a target="_blank" rel="noopener" href="<?php echo esc_url($m['receipt_url']); ?>">مشاهده رسید</a><?php endif;?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('avanik_payment_verify'); ?><input type="hidden" name="action" value="avanik_payment_verify"><input type="hidden" name="payment_id" value="<?php echo esc_attr($p['payment_id']); ?>"><button name="decision" value="approve" class="button button-primary">تأیید</button> <button name="decision" value="reject" class="button">رد</button></form></td></tr><?php endforeach;?></tbody></table></div><?php }
 public static function verify(): void { if(!current_user_can('manage_options')||!check_admin_referer('avanik_payment_verify'))wp_die('Unauthorized'); global $wpdb; $id=(int)($_POST['payment_id']??0); $decision=sanitize_key(wp_unslash($_POST['decision']??'')); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.PaymentRepository::table_name().' WHERE payment_id=%d',$id),ARRAY_A); if(!$p)wp_die('Payment not found'); if($decision==='approve'){ $wpdb->update(PaymentRepository::table_name(),['status'=>'paid','updated_at'=>current_time('mysql')],['payment_id'=>$id]); $wpdb->update(BookingRepository::table_name(),['status'=>'confirmed','updated_at'=>current_time('mysql')],['booking_id'=>(int)$p['booking_id']]); } elseif($decision==='reject') { $wpdb->update(PaymentRepository::table_name(),['status'=>'failed','updated_at'=>current_time('mysql')],['payment_id'=>$id]); } wp_safe_redirect(admin_url('admin.php?page=avanik-payment-verification')); exit; }
}